content:
@import 'tailwindcss';

:root {
  --ink: #172a4b;
  --muted: #8193b0;
  --blue: #237bff;
  --line: rgba(168, 195, 232, 0.28);
  --glass: rgba(250, 253, 255, 0.79);
}
* {
  box-sizing: border-box;
}
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}
body {
  font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
  color: var(--ink);
  font-size: 14px;
  background:
    radial-gradient(ellipse at 15% 0%, #e8f2ff 0, transparent 45%),
    radial-gradient(ellipse at 91% 14%, #e4f1fa 0, transparent 43%),
    linear-gradient(126deg, #c7dcf5, #dceaff 54%, #bfd7f0);
  --page-padding: 28px 32px;
  padding: var(--page-padding);
  -webkit-font-smoothing: antialiased;
}
/* Radix scroll locking must not resize the fixed-height map workspace. */
body[data-scroll-locked] { padding: var(--page-padding) !important; margin: 0 !important; }
body:before {
  content: '';
  position: fixed;
  pointer-events: none;
  width: 780px;
  height: 900px;
  border: 1px solid #c2dafa80;
  background: #b9d6ff20;
  transform: rotate(-34deg);
  border-radius: 200px;
  left: 44%;
  top: -480px;
}
button,
input,
select {
  font: inherit;
}
button {
  cursor: pointer;
  border: 0;
  background: none;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}
button:disabled {
  cursor: default;
  opacity: 0.35;
}
button,
a,
input,
select {
  outline: none;
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid #3384ff;
  outline-offset: 3px;
}
input:focus-visible,
select:focus-visible {
  border-color: #80b2ff !important;
  box-shadow: 0 0 0 3px #237bff12;
}
button {
  transition:
    background 0.16s,
    color 0.16s,
    box-shadow 0.16s,
    opacity 0.16s;
}
button:hover:enabled {
  filter: brightness(0.985);
}
h1,
h2,
p {
  margin: 0;
}
svg {
  flex-shrink: 0;
}
button svg {
  pointer-events: none;
}
button strong {
  font-weight: 600;
}
::selection {
  background: #cce2ff;
}
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-thumb {
  border-radius: 8px;
  background: #bbcde4a0;
}
::-webkit-scrollbar-track {
  background: transparent;
}
.glass {
  background: linear-gradient(118deg, rgba(255, 255, 255, 0.9), rgba(246, 251, 255, 0.72));
  border: 1px solid rgba(255, 255, 255, 0.9);
  box-shadow:
    0 5px 18px #386da00a,
    inset 0 1px 0 #fff9;
  backdrop-filter: blur(22px) saturate(135%);
}
.app-window {
  width: 100%;
  height: 100%;
  position: relative;
  border: 1px solid #ffffffe0;
  border-radius: 28px;
  box-shadow:
    0 20px 45px #4977ac21,
    0 2px 8px #58769e12;
  overflow: hidden;
  background: #edf5ffb8;
}
.trip-header {
  height: 64px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 19px 0 23px;
  border-bottom: 1px solid #c9daf344;
  background: linear-gradient(105deg, #fbfdffe8, #eff8ffba 65%, #fffffff0);
  backdrop-filter: blur(25px);
  position: relative;
  z-index: 40;
}
.window-dots {
  display: flex;
  gap: 8px;
  margin-right: 16px;
}
.window-dots i {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  box-shadow: inset 0 -1px 2px #0001;
  background: #ff625b;
}
.window-dots i:nth-child(2) {
  background: #ffbd38;
}
.window-dots i:nth-child(3) {
  background: #31c55a;
}
.brand-icon {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  background: #f8fbff9c;
  display: grid;
  place-items: center;
  color: var(--blue);
  margin-right: 1px;
}
.trip-header h1 {
  font-size: 19px;
  font-weight: 650;
  letter-spacing: 0.5px;
  max-width: 460px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.icon-button {
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #7187a8;
  border-radius: 9px;
  flex-shrink: 0;
  padding: 0;
}
.icon-button:hover:enabled {
  background: #e3effe;
  color: #216dda;
}
.trip-header > .icon-button {
  margin-left: 0;
}
.header-spacer {
  flex: 1;
}
.history-buttons {
  display: flex;
  gap: 8px;
  border-radius: 24px;
  padding: 4px 9px;
  background: #e8f0fa6b;
  margin-right: 5px;
}
.history-buttons .icon-button {
  width: 31px;
  color: #56708f;
}
.save-status {
  height: 37px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: #e2edf6b3;
  border: 1px solid #dbe7f37a;
  border-radius: 24px;
  color: #617593;
  padding: 0 17px;
  margin-right: 5px;
  font-size: 13px;
  font-weight: 550;
}
.saved-check {
  width: 15px;
  height: 15px;
  background: #42b980;
  border: 1px solid white;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: white;
}
.share-button {
  height: 39px;
  display: flex;
  align-items: center;
  gap: 9px;
  background: linear-gradient(110deg, #2079ff, #5ba2ff);
  color: white;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.3px;
  border: 1px solid #8abcff;
  border-radius: 22px;
  padding: 0 20px;
  box-shadow:
    0 4px 12px #247eff26,
    inset 0 1px 0 #ffffff55;
}
.share-button:hover {
  box-shadow: 0 5px 15px #247eff42;
}
.workspace {
  height: calc(100% - 64px);
  display: flex;
  min-height: 0;
}
.sidebar {
  width: 365px;
  flex-shrink: 0;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
  background: linear-gradient(125deg, #edf5ffe8, #e9f3ffd1);
  border-right: 1px solid #fff9;
  z-index: 20;
}
.trip-summary {
  border-radius: 20px 20px 15px 15px;
  padding: 17px 15px 19px;
  flex-shrink: 0;
  margin-bottom: 5px;
  box-shadow: none;
}
.summary-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
}
.summary-heading h2 {
  font-size: 18px;
  font-weight: 650;
}
.summary-stats {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.summary-stats > div {
  display: flex;
  align-items: center;
  gap: 9px;
}
.stat-icon {
  height: 36px;
  width: 36px;
  border: 1px solid #d9e7ff;
  background: #edf5ffd9;
  border-radius: 11px;
  display: grid;
  place-items: center;
  color: var(--blue);
}
.summary-stats strong {
  display: block;
  font-size: 16px;
  font-weight: 650;
  white-space: nowrap;
  line-height: 1.4;
}
.summary-stats small {
  display: block;
  color: var(--muted);
  font-size: 11px;
  margin-top: 4px;
  white-space: nowrap;
}
.day-list {
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
  flex: 1;
  padding: 2px 0 5px;
  scrollbar-gutter: stable;
}
.day-card {
  border: 1px solid #dbe7f6b0;
  border-radius: 14px;
  margin-bottom: 4px;
  background: linear-gradient(112deg, #ffffff9c, #f6faff80);
  position: relative;
  transition:
    border-color 0.15s,
    background 0.15s;
}
.day-card.active {
  border-color: #cddfff;
  background: linear-gradient(122deg, #eaf3ffcb, #f5f9ffad);
}
.day-heading {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 51px;
  padding: 0 7px 0 8px;
  gap: 0;
}
.day-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 0;
  min-height: 51px;
  text-align: left;
}
.day-number {
  color: white;
  background: var(--day-color);
  box-shadow:
    inset 0 2px 4px #ffffff30,
    0 2px 4px #2e81b60a;
  border: 1.5px solid white;
  width: 35px;
  height: 35px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  font-size: 19px;
  font-weight: 600;
}
.day-toggle strong {
  font-size: 15px;
  white-space: nowrap;
}
.day-date {
  color: #7186a8;
  white-space: nowrap;
  font-size: 11px;
  flex: 1;
}
.day-count {
  font-size: 11px;
  color: #7188ab;
  white-space: nowrap;
}
.day-toggle > .lucide {
  color: #7188ab;
  margin: 0 1px 0 0;
}
.rotated {
  transform: rotate(180deg);
}
.day-toggle .lucide,
.drawer-toggle > .lucide:last-child {
  transition: transform 0.2s;
}
.day-heading > .more-menu {
  width: 0;
  overflow: hidden;
  opacity: 0;
  transition:
    width 0.15s,
    opacity 0.15s;
}
.day-heading:hover > .more-menu,
.day-heading:focus-within > .more-menu {
  width: 24px;
  opacity: 1;
  overflow: visible;
}
.day-heading:hover .day-count,
.day-heading:focus-within .day-count {
  display: none;
}
.day-heading > .more-menu > .icon-button {
  width: 24px;
}
.day-content {
  padding: 0 6px 5px;
}
.route-card {
  background: #fcfdff94;
  border: 1px solid #e0ebf7af;
  border-radius: 12px;
  margin-bottom: 4px;
  transition: border-color 0.15s;
}
.route-heading {
  display: flex;
  align-items: center;
  min-height: 44px;
  padding: 0 6px 0 17px;
  gap: 4px;
}
.route-card.active-route {
  border-color: #d2e3fc;
  background: #fcfdffd9;
}
.route-toggle {
  display: flex;
  align-items: center;
  gap: 11px;
  flex: 1;
  min-width: 0;
  text-align: left;
  padding: 0;
}
.route-toggle strong {
  font-size: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.route-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px white;
  flex-shrink: 0;
}
.route-count {
  font-size: 11px;
  color: var(--muted);
  white-space: nowrap;
}
.route-actions {
  display: none;
  gap: 0;
}
.route-actions .icon-button {
  width: 25px;
  height: 26px;
}
.route-heading:hover .route-actions,
.route-heading:focus-within .route-actions {
  display: flex;
}
.route-heading:hover .route-count,
.route-heading:focus-within .route-count {
  display: none;
}
.route-hidden .route-toggle {
  opacity: 0.5;
}
.stop-list {
  position: relative;
  margin: 0 11px 0 30px;
  padding-bottom: 0;
}
.stop-list:before {
  content: '';
  position: absolute;
  left: -12px;
  top: -13px;
  bottom: 41px;
  border-left: 1px dashed #c8d6eb;
}
.stop-card {
  min-height: 72px;
  height: auto;
  padding: 11px 0;
  border: 1px solid #dfe8f5b3;
  border-radius: 11px;
  display: flex;
  align-items: center;
  background: linear-gradient(110deg, #ffffffeb, #f7faffbb);
  box-shadow: 0 3px 7px #4c78a404;
  position: relative;
  transition:
    border-color 0.15s,
    background 0.15s;
  touch-action: none;
}
.stop-card:before {
  content: '';
  position: absolute;
  left: -16px;
  top: 23px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #a9bedb;
  box-shadow: 0 0 0 2px #f8fbff;
}
.stop-card:hover {
  border-color: #bcd6f8;
  background: #fff;
}
.stop-card.selected {
  border-color: #7fb0ff;
  background: #f0f7ff;
  box-shadow: 0 0 0 2px #237bff08;
}
.drag-handle {
  width: 29px;
  min-width: 29px;
  height: 34px;
  display: grid;
  place-items: center;
  color: #89a0c0;
  cursor: grab;
  padding: 0;
  touch-action: none;
}
.drag-handle:hover {
  color: #237bff;
}
.drag-handle:active {
  cursor: grabbing;
}
.stop-main {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  min-width: 0;
  text-align: left;
  height: 100%;
}
.stop-number {
  height: 24px;
  width: 24px;
  flex-shrink: 0;
  border: 1px solid #fff9;
  color: white;
  border-radius: 50%;
  font-size: 13px;
  display: grid;
  place-items: center;
  box-shadow:
    0 3px 8px #237bff21,
    inset 0 2px 7px #ffffff30;
}
.stop-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 4px;
  flex: 1;
}
.stop-text strong {
  font-size: 13px;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stop-text small {
  font-size: 9px;
  color: #97a7bd;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.5;
  max-width: 100%;
}
.stop-card > .more-menu {
  margin: 0 5px 0 3px;
}
.stop-card .icon-button {
  width: 23px;
}
.insertion-target {
  height: 8px;
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
}
.insertion-target span {
  height: 2px;
  width: 100%;
  border-radius: 3px;
  background: transparent;
  position: relative;
}
.insertion-target.over span {
  background: #237bff;
  box-shadow: 0 0 0 2px #237bff12;
}
.insertion-target.over span:before {
  content: '';
  width: 6px;
  height: 6px;
  background: white;
  border: 2px solid #237bff;
  position: absolute;
  left: -3px;
  top: -2px;
  border-radius: 50%;
}
.insertion-target.enabled {
  height: 8px;
}
.text-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  color: #7b94b5;
  font-size: 11px;
}
.text-button:hover {
  color: var(--blue);
}
.add-stop {
  height: 24px;
  width: 100%;
  padding-bottom: 5px;
}
.add-route {
  height: 23px;
  width: 100%;
  padding-top: 2px;
}
.sidebar-footer {
  border-radius: 18px;
  padding: 7px 8px;
  flex-shrink: 0;
  margin-top: 0;
  background: #f9fcffe0;
}
.add-day {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 41px;
  border-radius: 20px;
  border: 1px solid #bed8ff;
  background: linear-gradient(110deg, #eef6ff, #eaf3ff);
  color: var(--blue);
  font-size: 15px;
  font-weight: 600;
  box-shadow: 0 2px 5px #327cf007;
}
.add-day:hover {
  background: #dfedff;
}
.day-drop-hint {
  position: absolute;
  left: var(--day-copy-start);
  right: 10px;
  top: 1px;
  padding: 2px 7px;
  pointer-events: none;
  white-space: nowrap;
  border: 1px dashed #a9cafa;
  border-radius: 8px;
  color: #347bd3;
  font-size: 11px;
  line-height: 18px;
  background: #e9f3ff;
}
.drop-over {
  border-color: #3688ff !important;
  box-shadow: 0 0 0 2px #237bff20 !important;
  background: #e6f1ffcc !important;
}
.drag-source {
  opacity: 0.3;
}
.drag-preview {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 160px;
  max-width: 280px;
  height: 55px;
  border-radius: 13px;
  padding: 0 14px;
  box-shadow: 0 12px 28px #294c7a26;
  color: #237bff;
  cursor: grabbing;
}
.drag-preview strong {
  color: var(--ink);
  font-size: 14px;
}
.route-updating {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  color: #8a9cb5;
  padding: 2px 0 5px;
}
.route-updating i {
  width: 5px;
  height: 5px;
  background: #74a9ec;
  border-radius: 50%;
  animation: pulse 1s infinite;
}
.route-error {
  font-size: 10px;
  color: #cd7864;
  padding: 5px 0;
}
.route-error button {
  color: #237bff;
  text-decoration: underline;
}
.route-empty {
  font-size: 10px;
  color: #9aa9bd;
  padding: 10px 0;
  text-align: center;
}
.empty-day {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  color: #90a4c1;
  padding: 26px 8px;
}
.empty-day strong {
  font-size: 13px;
  font-weight: 500;
  color: #6d85a7;
}
.empty-day span {
  font-size: 11px;
}
.empty-day button {
  font-size: 11px;
  color: var(--blue);
  background: #eaf3ff;
  padding: 7px 12px;
  border-radius: 8px;
}
.map-area {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  background: #eef2ef;
}
.map-view {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.map-canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
  touch-action: none;
}
.map-canvas:active {
  cursor: grabbing;
}
.cartography {
  pointer-events: none;
}
.district-labels {
  font-family: 'Microsoft YaHei', sans-serif;
  font-size: 21px;
  font-weight: 600;
  fill: #8293a8;
  paint-order: stroke;
  stroke: #ffffffb8;
  stroke-width: 3;
}
.street-labels {
  font-family: 'Microsoft YaHei', sans-serif;
  font-size: 9px;
  fill: #adbac2;
  letter-spacing: 1px;
  paint-order: stroke;
  stroke: #fff9;
  stroke-width: 2;
}
.map-marker,
.favorite-marker {
  cursor: pointer;
  outline: none;
}
.map-marker:focus-visible circle,
.favorite-marker:focus-visible circle {
  stroke: #102f66;
  stroke-width: 3;
}
.map-marker:hover > circle {
  filter: brightness(1.04);
}
.route-polyline {
  cursor: pointer;
  outline: none;
}
.route-polyline:focus-visible > polyline:nth-child(2) {
  stroke: #aacaff;
}
.map-controls {
  position: absolute;
  right: 18px;
  bottom: 85px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: bottom 0.25s;
}
.map-controls.drawer-open {
  bottom: 179px;
}
.map-controls > .icon-button,
.zoom-controls {
  background: #ffffffe6;
  border: 1px solid #fff;
  box-shadow: 0 4px 15px #587eac16;
  backdrop-filter: blur(15px);
  border-radius: 14px;
  color: #284369;
}
.map-controls > .icon-button {
  width: 42px;
  height: 42px;
}
.zoom-controls {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.zoom-controls .icon-button {
  width: 42px;
  height: 39px;
  border-radius: 0;
  color: #284369;
}
.zoom-controls .icon-button + .icon-button {
  border-top: 1px solid #e5ecf5;
}
.map-attribution {
  position: absolute;
  bottom: 75px;
  left: 18px;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 9px;
  color: #92a5b5;
  pointer-events: none;
  transition: bottom 0.25s;
}
.map-attribution.drawer-open {
  bottom: 172px;
}
.map-scale {
  padding: 0 8px 3px;
  border-bottom: 2px solid #8fa3b388;
  position: relative;
  min-width: 55px;
  text-align: center;
  color: #7f92a4;
}
.map-scale:before,
.map-scale:after {
  position: absolute;
  content: '';
  bottom: -1px;
  height: 5px;
  border-left: 1px solid #8fa3b388;
}
.map-scale:before {
  left: 0;
}
.map-scale:after {
  right: 0;
}
.place-search {
  position: absolute;
  right: 18px;
  top: 18px;
  width: 342px;
  z-index: 30;
}
.search-input-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 55px;
  padding: 7px 11px 7px 16px;
  border-radius: 18px;
  background: linear-gradient(115deg, #fffefcfa, #f5faffea);
  border: 6px solid #f5f9ffa6;
  box-shadow:
    0 4px 17px #36619113,
    inset 0 0 0 1px #d8e7f9;
  color: #365071;
}
.search-input-wrap.focused {
  box-shadow:
