.favorite-drawer {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 13px;
  border-radius: 24px;
  z-index: 28;
  background: linear-gradient(112deg, #ffffffed, #edf8ffd1 60%, #fcfdffed);
  box-shadow:
    0 9px 23px #426a991c,
    inset 0 1px 0 #fff;
  overflow: hidden;
  transition: height 360ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 180ms ease;
}
.favorite-drawer.resizing {
  transition: none;
  box-shadow: 0 -8px 34px #426a9924, inset 0 1px 0 #fff;
}
.drawer-heading {
  width: 100%;
  height: 64px;
  padding: 13px 22px 0;
  display: flex;
  align-items: center;
  gap: 13px;
  position: relative;
  text-align: left;
}
.drawer-grabber {
  position: absolute;
  width: 80px;
  height: 26px;
  left: calc(50% - 40px);
  top: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  cursor: ns-resize;
  touch-action: none;
  border-radius: 0 0 14px 14px;
}
.drawer-grabber:hover, .drawer-grabber:focus-visible {
  background: #dcecff80;
}
.drawer-grabber-shape {
  position: relative;
  width: 38px;
  height: 12px;
}
.drawer-grabber-shape::before, .drawer-grabber-shape::after {
  content: '';
  position: absolute;
  top: 5px;
  width: 20px;
  height: 4px;
  background: #9cbcdf;
  border-radius: 4px;
  transition: transform 200ms cubic-bezier(0.22, 1, 0.36, 1), background 150ms;
}
.drawer-grabber-shape::before { left: 0; transform-origin: right center; }
.drawer-grabber-shape::after { right: 0; transform-origin: left center; }
.drawer-grabber:is(:hover, :focus-visible) .drawer-grabber-shape::before,
.resizing .drawer-grabber-shape::before { transform: rotate(-20deg); background: #5d9de9; }
.drawer-grabber:is(:hover, :focus-visible) .drawer-grabber-shape::after,
.resizing .drawer-grabber-shape::after { transform: rotate(20deg); background: #5d9de9; }
.drawer-grabber[data-direction='down']:is(:hover, :focus-visible) .drawer-grabber-shape::before,
.resizing .drawer-grabber[data-direction='down'] .drawer-grabber-shape::before { transform: rotate(20deg); }
.drawer-grabber[data-direction='down']:is(:hover, :focus-visible) .drawer-grabber-shape::after,
.resizing .drawer-grabber[data-direction='down'] .drawer-grabber-shape::after { transform: rotate(-20deg); }
.favorite-drawer:not(.expanded) .favorite-list {
