}
.favorite-list {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: min(246px, 100%);
  justify-content: start;
  align-items: center;
  align-content: start;
  gap: 8px 10px;
  height: calc(100% - 70px);
  margin: 0 12px;
