}
.favorite-list::-webkit-scrollbar { height: 5px; }
.favorite-list::-webkit-scrollbar-track { background: #deebf780; border-radius: 10px; }
.favorite-list::-webkit-scrollbar-thumb { background: #a8c7ee; border-radius: 10px; }
.favorite-list::-webkit-scrollbar-thumb:hover { background: #79a8e1; }
.favorite-list::-webkit-scrollbar-button { display: none; width: 0; height: 0; }
@supports selector(::-webkit-scrollbar) {
  .favorite-list { scrollbar-width: auto; scrollbar-color: auto; }
}
.favorite-list:has(.favorite-empty) { display: flex; }
.map-controls, .map-controls.drawer-open {
