  flex: 1;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 36px;
  border-radius: 10px;
  color: #8598b3;
  font-size: 13px;
}
.transfer-tabs button[aria-selected='true'] {
  color: #237bff;
  background: #fff;
  box-shadow: 0 2px 8px #7393b412;
}
.transfer-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}
.transfer-toolbar > span {
  font-size: 11px;
  color: #8a9bb2;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.transfer-toolbar button {
  flex-shrink: 0;
  color: #3d82df;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.preview-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 2px 10px;
  font-size: 11px;
  color: #8195b0;
}
.preview-heading button {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #4c83cb;
}
.import-preview-button {
  width: 100%;
  padding: 0;
  text-align: left;
  border-radius: 13px;
  border: 1px solid #dce8f8;
  background: #ffffffb3;
  overflow: hidden;
}
.import-preview-button:hover {
  border-color: #a6c8f8;
}
.itinerary-preview {
  background: #ffffff9c;
  border: 1px solid #e0eaf6;
  border-radius: 13px;
