  overflow-y: auto;
  text-align: left;
}
.import-preview-button .itinerary-preview {
  border: 0;
  border-radius: 0;
  background: none;
}
.itinerary-preview h3 {
  font-size: 16px;
  font-weight: 650;
  margin: 0 0 7px;
}
.preview-counts {
  font-size: 10px;
  color: #91a3b9;
  margin-bottom: 20px;
}
.preview-day {
  margin-top: 17px;
}
.preview-day h4 {
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  font-weight: 600;
}
.preview-day h4 i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}
.preview-day h4 span {
  font-size: 10px;
  color: #90a1b8;
  font-weight: 400;
  margin-left: auto;
}
.preview-day p {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-left: 15px;
  font-size: 10px;
  color: #8c9cb2;
  line-height: 1.7;
  margin-top: 7px;
}
.preview-day p strong {
  color: #637b9c;
  font-size: 11px;
  font-weight: 500;
}
.preview-empty {
  color: #91a4bc;
  font-size: 11px;
}
.preview-edit-hint {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  font-size: 10px;
  color: #819cbd;
  border-top: 1px solid #e6eff9;
  background: #f4f8fe88;
}
.json-editor {
  display: block;
  width: 100%;
  height: 310px;
  resize: vertical;
  max-height: 45vh;
  min-height: 160px;
  padding: 13px;
  border: 1px solid #cbdff9;
  border-radius: 12px;
  background: #fbfdff;
  color: #526f94;
  font:
    11px/1.75 Consolas,
    monospace;
  outline: none;
  tab-size: 2;
}
.json-editor:focus {
  border-color: #8fbaff;
  box-shadow: 0 0 0 3px #237bff08;
}
.transfer-error {
  font-size: 11px;
  color: #c6676c;
  padding: 11px 12px;
  border: 1px solid #efdadd;
  background: #fff4f5;
  border-radius: 9px;
  margin-top: 11px;
  overflow-wrap: anywhere;
}
.transfer-warnings {
  color: #9c8b65;
  background: #fffbf1;
  border-radius: 9px;
  font-size: 10px;
  line-height: 1.7;
  padding: 9px 12px;
  margin-top: 10px;
}
.transfer-footer {
  margin-top: 19px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.transfer-footer > span {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #8c9fb7;
  font-size: 10px;
}
.transfer-footer > span svg {
  color: #58af85;
}
.export-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 17px;
}
.export-options > button {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px;
  border: 1px solid #dce8f7;
  background: #ffffffae;
  border-radius: 13px;
  text-align: left;
}
.export-options > button:hover:enabled {
  background: #f1f7ff;
  border-color: #b6d2f8;
}
.export-type-icon {
  height: 38px;
  width: 38px;
  display: grid;
  place-items: center;
  background: #edf5ff;
  border: 1px solid #dceaff;
  border-radius: 11px;
  color: #4189ec;
}
.export-options > button > span:nth-child(2) {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.export-options strong {
  font-size: 12px;
  font-weight: 600;
}
.export-options small {
  font-size: 10px;
  color: #8da0b9;
}
.export-options > button > svg {
  color: #82a1c6;
}
