.annotation-colors button { width:22px; height:22px; display:grid; place-items:center; border:3px solid white; outline:1px solid transparent; border-radius:50%; color:white; }
.annotation-colors button[aria-pressed=true] { outline-color:#b8c5d9; }
.annotation-undo { display:flex; align-items:center; gap:4px; color:#71839c; font-size:11px; }
.annotation-undo:disabled { opacity:.4; cursor:default; }
.annotation-hint { min-height:30px; padding-top:12px; font-size:10px; line-height:1.7; color:#8b99ac; }
.annotation-actions { display:grid; grid-template-columns:1fr 1fr; gap:7px; border-top:1px solid #edf0f5; padding-top:10px; margin-top:8px; }
.annotation-actions button { display:flex; align-items:center; justify-content:center; gap:4px; font-size:11px; min-height:34px; border-radius:10px; color:#8b7e80; background:#f8f5f5; white-space:nowrap; }
.annotation-actions .annotation-keep { background:#eaf2ff; color:#3773bd; }
.annotation-actions button:hover { filter:brightness(.98); }
.annotation-panel button:focus-visible, .annotation-launcher:focus-visible { outline:2px solid #3773bd; outline-offset:3px; }
.transfer-card { position:relative; margin:2px 6px 10px 16px; padding:8px 10px; border:1px solid #d9e6f5; border-radius:11px; background:linear-gradient(120deg,#edf5ffb8,#f7faffaa); font-size:10px; color:#7790af; }
.transfer-card:before { content:''; position:absolute; left:-9px; top:-9px; bottom:-9px; border-left:1px dashed #a8c2e3; }
.transfer-card-heading { display:flex; align-items:center; gap:8px; margin-bottom:6px; }
.transfer-card-heading > span { display:flex; align-items:center; gap:4px; font-size:10px; color:#5c7da5; font-weight:600; }
.transfer-card-heading label { margin-left:auto; display:flex; align-items:center; gap:4px; cursor:pointer; font-size:10px; white-space:nowrap; }
.transfer-card-heading input { width:12px; height:12px; accent-color:#3986f5; }
.transfer-card-heading .icon-button { width:21px; height:21px; padding:3px; }
.transfer-endpoints { display:flex; align-items:center; gap:7px; font-size:11px; color:#405e83; line-height:1.6; margin-bottom:7px; }
.transfer-endpoints span { flex:1; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.transfer-endpoints svg { flex-shrink:0; color:#89a6c9; }
.transfer-card-controls { display:flex; gap:8px; align-items:center; justify-content:space-between; }
.transfer-card-controls > span { text-align:right; line-height:1.5; font-variant-numeric:tabular-nums; }
.transfer-card .glass-select-trigger { width:76px; min-height:27px; font-size:10px; padding:4px 8px; flex-shrink:0; }
.transfer-planned-time { display:flex; align-items:center; gap:7px; margin-top:8px; }
.transfer-card .schedule-notes { margin-bottom:0; }
.transfer-disabled { background:#f5f8fc9c; border-color:#e1e8f2; }
.transfer-retry { font-size:10px; color:#b57157; text-align:left; margin-top:7px; line-height:1.5; }
.schedule-modal { width:min(460px,calc(100vw - 32px)); }
.schedule-form { display:grid; gap:15px; }
.schedule-form label { display:grid; gap:7px; font-size:12px; color:#58718f; min-width:0; }
.schedule-form input:not([type=checkbox]), .schedule-form textarea, .schedule-form select { width:100%; min-width:0; padding:10px 12px; border:1px solid #d6e5f8; border-radius:10px; background:#ffffffc4; color:#284564; font:inherit; outline:none; }
.schedule-form input:focus, .schedule-form textarea:focus, .schedule-form select:focus { border-color:#79acfb; box-shadow:0 0 0 3px #237bff0c; }
.schedule-form small { font-size:10px; color:#8a9bb0; }
.schedule-time-fields { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
.schedule-form .schedule-next-day { display:flex; align-items:center; gap:7px; }
.schedule-help { display:flex; align-items:center; gap:6px; color:#8b9db3; font-size:11px; line-height:1.6; margin:0; }
.schedule-help svg { flex-shrink:0; }
.schedule-footer { display:flex; justify-content:flex-end; align-items:center; gap:20px; }
.transfer-modal { width:660px; height:min(820px,90dvh); display:flex; flex-direction:column; overflow:hidden; max-height:90vh; }
.transfer-modal > .modal-heading, .transfer-modal > .transfer-tabs, .transfer-modal > .import-prompt-card { flex-shrink:0; }
.transfer-modal > [role=tabpanel] { flex:1; min-height:0; overflow-y:auto; padding-right:4px; scrollbar-gutter:stable; animation:ai-panel-in 180ms ease-out; }
.transfer-modal .transfer-footer { gap:10px; flex-wrap:wrap; }
.repair-batch-actions { display:flex; flex-wrap:wrap; gap:10px; margin:12px 0; flex-shrink:0; }
@media(prefers-reduced-motion:reduce) { .transfer-modal > [role=tabpanel] { animation:none; } }
.transfer-modal .transfer-footer { position:sticky; bottom:0; padding:14px 0 2px; background:#f0f6ff; z-index:1; }
.transfer-modal .itinerary-preview { max-height:245px; }
.transfer-modal .prompt-copy-text { max-height:160px; }
.import-prompt-card { margin:4px 0 16px; padding:13px 14px; border:1px solid #d8e7fb; border-radius:13px; background:linear-gradient(110deg,#eaf3ffb0,#ffffffb0); }
.import-prompt-card > div:first-child { display:flex; align-items:center; gap:10px; color:#4a83cc; }
.import-prompt-card strong, .ai-import-toolbar strong { display:block; font-size:12px; color:#355982; }
.import-prompt-card small { display:block; font-size:10px; color:#879eb8; margin-top:4px; line-height:1.6; }
.import-prompt-actions { display:flex; align-items:center; gap:15px; justify-content:flex-end; margin-top:10px; }
.import-prompt-actions .text-button { font-size:11px; gap:5px; }
.prompt-copy-text { display:block; width:100%; height:210px; margin-top:12px; resize:vertical; border:1px solid #d5e4f7; border-radius:9px; padding:12px; background:#ffffffbb; color:#567390; font-size:11px; line-height:1.7; }
.ai-import-toolbar { display:flex; align-items:center; gap:15px; margin:8px 0 18px; }
.ai-import-toolbar p { margin:5px 0 0; color:#889bb2; font-size:10px; line-height:1.6; }
.ai-import-button { display:flex; align-items:center; gap:6px; white-space:nowrap; flex-shrink:0; border:1px solid #cfe0fa; border-radius:9px; padding:9px 11px; color:#357bd6; background:#edf5ff; font-size:11px; }
.ai-import-button:hover { background:#e2efff; }
.ai-import-button:disabled { opacity:.5; cursor:default; }
.ai-import-candidate { background:#f3f8ff; padding:12px; border:1px solid #bdD7fb; border-radius:12px; margin-bottom:18px; }
.restore-import { margin-bottom:12px; font-size:11px; }
.preview-day h4 { overflow-wrap:anywhere; }
.preview-day p > small, .preview-transfer small { display:block; color:#7792b3; font-size:10px; margin:3px 0; }
.preview-day .preview-notes { overflow:hidden; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; }
.preview-day .preview-transfer { display:flex; align-items:flex-start; gap:7px; padding:8px 9px; margin:8px 0; border-radius:8px; background:#edf4fd; font-size:10px; color:#6686ab; }
.preview-transfer svg { flex-shrink:0; margin-top:3px; }
.preview-transfer span { overflow-wrap:anywhere; }
.preview-visit-details { font-size:11px; color:#718dab; margin:8px 0 12px; }
.preview-visit-details summary { cursor:pointer; padding:5px 0; }
.preview-visit-details > div { border-left:1px solid #d6e5f7; padding:6px 10px; }
.preview-visit-details strong { display:block; margin-bottom:4px; color:#52749a; }
.import-preview-button .preview-edit-hint { width:100%; }
.transfer-modal .json-editor { height:260px; min-height:150px; }
@media(max-width:600px) { .ai-import-toolbar { flex-wrap:wrap; } .transfer-modal { padding:18px; } }
